```lean
intro hfg
let n := Fintype.card ι
let s_f := ∑ i, f i
let s_g := ∑ i, g i
let s_fg := ∑ i, f i * g i
have h1 : ∀ i j, f i * g j + f j * g i ≤ f i * g i + f j * g j :=
  by intro i j; rw [add_comm]; apply (hfg i j)
let h2 : ∀ i j, f i * g j + f j * g i ≤ f i * g i + f j * g j :=
  by intro i j; exact h1 i j
let h3 : (∑ i, ∑ j, f i * g j) + (∑ i, ∑ j, f j * g i) ≤
  (∑ i, ∑ j, f i * g i) + (∑ i, ∑ j, f j * g j) :=
  by { rw [sum_add_distrib, sum_add_distrib], apply sum_le_sum; intro i j; exact h2 i j }
let h4 : ∑ i, ∑ j, f i * g j = ∑ i, ∑ j, f j * g i :=
  by { rw [sum_swap], congr' }
let h5 : ∑ i, ∑ j, f i * g j = s_f * s_g :=
  by { rw [sum_mul], congr' }
let h6 : ∑ i, ∑ j, f j * g i = s_f * s_g :=
  by { rw [sum_swap, sum_mul], congr' }
let h7 : (∑ i, ∑ j, f i * g j) + (∑ i, ∑ j, f j * g i) = 2 * s_f * s_g :=
  by { rw [h5, h6], congr', rw [add_assoc, add_comm], rw [mul_add], congr' }
let h8 : (∑ i, ∑ j, f i * g i) + (∑ i, ∑ j, f j * g j) = s_f * s_f + s_g * s_g :=
  by { rw [sum_mul, sum_mul], congr', rw [add_assoc, add_comm], congr' }
let h9 : 2 * s_f * s_g ≤ s_f * s_f + s_g * s_g :=
  by { rw [h7, h8], apply h3 }
have h10 : ↑n * s_fg ≤ s_f * s_g :=
  by { rw [s_fg], apply mul_le_mul_left; exact (le_refl n).trans (le_add_right (le_zero (le_refl s_fg)) (le_refl s_fg)) }
apply (le_trans h9 h10)
